from pathlib import Path
import pandas as pd,numpy as np,json
O=Path('outputs');W=Path('work');b=pd.read_csv(O/'stage6_foxp2_gnomad_narrow_variants.csv');d=pd.read_csv(O/'stage6_foxp2_fi_cohort_region_aligned.csv');R=np.fromfile(W/'stage6_foxp2_gnomad_nfe_narrow_ld.bin',dtype='<f8').reshape(len(b),len(b));idx=b.set_index('rs').index.get_indexer(d.rs);anchor=b.index[b.rs.eq('rs12536335')];assert (idx>=0).all() and len(anchor)==1;d['r_anchor']=R[idx,anchor[0]];d['ukb_aligned_to_anchor_phase']=d.ukb_z*np.sign(d.r_anchor);d['tg_aligned_to_anchor_phase']=d.tg_z_adapter*np.sign(d.r_anchor);s=d[d.r_anchor.abs()>=np.sqrt(.8)].copy();s.to_csv(O/'stage6_foxp2_fi_cohort_high_ld.csv',index=False);j={'reference_population':'gnomAD NFE','anchor':'rs12536335','threshold_r2':.8,'n_markers':len(s),'n_opposite_sign':int((s.ukb_z*s.tg_z_adapter<0).sum()),'ukb_median_phase_z':float(s.ukb_aligned_to_anchor_phase.median()),'tg_median_phase_z':float(s.tg_aligned_to_anchor_phase.median()),'caveat':'Correlated markers are not independent observations; sign adapter inferred not confirmed; reference LD is external.'};(O/'stage6_foxp2_fi_cohort_high_ld.json').write_text(json.dumps(j,indent=2)+'\n');print(j)
